INSERT INTO public.content_collections (key, data, updated_at) VALUES ('styles', '[{"id":"family","media":"mountains","title":{"en":"Family Adventures","ar":"مغامرات عائلية","ro":"Aventuri în familie"},"intro":{"en":"Unhurried days, rest built in, and activities chosen around your children''s ages. Suitability is informative, never a safety guarantee.","ar":"أيام هادئة الإيقاع مع وقت للراحة، وأنشطة تٌختار وفق أعمار أطفالك. الملاءمة معلومة استرشادية وليست ضمانًا للسلامة.","ro":"Zile fără grabă, timp de odihnă și activități alese după vârsta copiilor. Potrivirea este informativă, nu o garanție de siguranță."}},{"id":"private","media":"oldTown","title":{"en":"Private & Premium","ar":"خاصة ومميزة","ro":"Privat și premium"},"intro":{"en":"Private transfers, refined stays and personal pacing can be requested, subject to supplier confirmation.","ar":"يمكن طلب تنقلات خاصة وإقامة راقية وإيقاع شخصي، مع خضوعها لتأكيد المزودين.","ro":"Transferuri private, cazări rafinate și un ritm personal pot fi solicitate, sub rezerva confirmării furnizorilor."}},{"id":"nature","media":"mountains","title":{"en":"Mountains & Nature","ar":"الجبال والطبيعة","ro":"Munți și natură"},"intro":{"en":"Carpathian forests, cool summer air and wide valleys — with routes adapted to weather and season.","ar":"غابات الكاربات وهواء الصيف المنعش والوديان الفسيحة، مع مسارات تتكيّف مع الطقس والموسم.","ro":"Păduri carpatine, aer răcoros de vară și văi largi — cu trasee adaptate vremii și sezonului."}},{"id":"heritage","media":"oldTown","title":{"en":"History & Heritage","ar":"التاريخ والتراث","ro":"Istorie și patrimoniu"},"intro":{"en":"Castles, fortified towns and painted traditions, explored at a pace that leaves room to linger.","ar":"قلاع وبلدات محصّنة وتقاليد عريقة، تٌستكشف بإيقاع يترك مجالًا للتأمل.","ro":"Castele, cetăți și tradiții, descoperite într-un ritm care lasă loc pentru răgaz."}},{"id":"romantic","media":"countryside","title":{"en":"Romantic Escapes","ar":"رحلات رومانسية","ro":"Escapade romantice"},"intro":{"en":"Quiet mountain mornings and old-town evenings for couples who prefer calm over crowds.","ar":"صباحات جبلية هادئة وأمسيات في البلدات القديمة للأزواج الذين يفضّلون السكينة على الازدحام.","ro":"Dimineți liniștite la munte și seri în orașe vechi, pentru cuplurile care preferă liniștea."}},{"id":"groups","media":"countryside","title":{"en":"Custom Groups","ar":"مجموعات مخصصة","ro":"Grupuri personalizate"},"intro":{"en":"Friends, extended families or small corporate groups — including pilot groups of around 10–12 travellers.","ar":"أصدقاء أو عائلات ممتدة أو مجموعات عمل صغيرة، بما في ذلك مجموعات تجريبية من نحو 10 إلى 12 مسافرًا.","ro":"Prieteni, familii extinse sau grupuri mici de companie — inclusiv grupuri pilot de aproximativ 10–12 persoane."}}]'::jsonb, now()) ON CONFLICT (key) DO NOTHING;